@@ -27,4 +27,26 @@
 <div class="overlay" id="startOverlay"><div class="card"><div class="eyebrow">A small creature, a very big day</div><h1>WORM<br><span>LAND.</span></h1><p>Eat your way up from the quiet fields. Get bigger, get noticed, and send the whole countryside scrambling.</p><div class="feature-row"><span class="feature">Dig & dive</span><span class="feature">Pop-up physics</span><span class="feature">Earn mutations</span></div><button class="primary" id="startBtn">Burrow in&nbsp; →</button><div class="card-foot">JUST STEER. THE WORM DOES THE REST.</div></div></div>
 <div class="overlay hidden" id="endOverlay"><div class="card game-over"><div class="eyebrow">The field fought back</div><h1>WELL<br><span>DUg.</span></h1><p id="endCopy">The countryside will tell stories about you.</p><div class="end-stats"><div><strong id="endSize">0</strong><span>Metres long</span></div><div><strong id="endScore">0</strong><span>Things eaten</span></div><div><strong id="endLevel">0</strong><span>Mutations</span></div></div><button class="primary" id="restartBtn">Have another go&nbsp; ↗</button></div></div>
 </main>
 <script>
+(()=>{
+const canvas=document.querySelector('#scene'),ctx=canvas.getContext('2d');
+const $=s=>document.querySelector(s), W=()=>innerWidth,H=()=>innerHeight;
+let w=0,h=0,dpr=1,last=0,playing=false,over=false,elapsed=0,score=0,damage=0,level=0,threat=0,shake=0;
+let camera={x:0,y:0},worm,foods=[],sparks=[],enemies=[],shots=[],landmarks=[],keys={},pointer={x:0,y:0,active:false},milestoneTimer=0,spawnTimer=0;
+const upgrades=[
+ {name:'Spring spine',desc:'Faster bursts from the earth',icon:'↗'},
+ {name:'Velvet scales',desc:'Brush off one extra hit',icon:'✳'},
+ {name:'Snack radar',desc:'A wider pull for nearby snacks',icon:'⌁'},
+ {name:'Turbo tail',desc:'A little more speed, all the time',icon:'»'},
+ {name:'Deep diver',desc:'Stay hidden longer underground',icon:'↓'}
+];
+const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
+function surface(x){return h*.59+Math.sin(x*.0014)*30+Math.sin(x*.0041+1.4)*9}
+function resize(){dpr=Math.min(devicePixelRatio||1,2);w=W();h=H();canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);if(!pointer.active){pointer.x=w*.7;pointer.y=h*.5}}
+addEventListener('resize',resize);resize();
+function start(){score=0;damage=0;level=0;threat=0;elapsed=0;over=false;playing=true;foods=[];sparks=[];enemies=[];shots=[];landmarks=[];spawnTimer=0;camera={x:0,y:0};worm={x:0,y:surface(0)+45,vx:2,vy:0,angle:0,speed:2.5,r:9,trail:[],pop:0,air:0,invuln:0,hidden:0};for(let i=0;i<38;i++)addFood(rand(-800,1900));$('#startOverlay').classList.add('hidden');$('#endOverlay').classList.add('hidden');$('#statusText').textContent='FIELD NOTES · 01';updateHUD();last=performance.now();requestAnimationFrame(loop)}
+function addFood(x){let surf=surface(x),und=Math.random()<.25,y=und?surf+rand(45,180):surf-rand(35,145);foods.push({x,y,r:und?rand(6,9):rand(7,11),type:und?'root':['person','cow','crate'][Math.floor(Math.random()*3)],phase:rand(0,7),value:und?2:1})}
+function addSpark(x,y,color,n=8){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),v=rand(1,5);sparks.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rand(.35,.8),max:.8,color,r:rand(2,5)})}}
+function updateHUD(){let size=Math.max(1,1+Math.floor(score/3));$('#sizeValue').textContent=String(size).padStart(2,'0');$('#scoreValue').textContent=String(score).padStart(2,'0');threat=Math.min(100,score*2.15);$('#threatFill').style.width=threat+'%';$('#threatText').textContent=threat<18?'QUIET':threat<42?'CURIOUS':threat<70?'ALARMED':'LOCKDOWN';$('#threatNote').textContent=threat<18?'No one has noticed you.':threat<42?'A few boots on the ground.':threat<70?'Air patrols have arrived.':'The whole county is after you.';$('#upgradeName').textContent=upgrades[level%upgrades.length].name;$('#upgradeDesc').textContent=upgrades[level%upgrades.length].desc;$('#upgradeIcon').textContent=upgrades[level%upgrades.length].icon;let left=5-score%5;$('#upgradeCount').textContent=left;$('#upgradeProgress').style.width=((score%5)/5*100)+'%'}
+function notice(text){let el=$('#milestone');el.textContent=text;el.classList.add('show');milestoneTimer=2.2}
+function eat(f){score+=f.value;addSpark(f.x,f.y,f.type==='root'?'#d6f263':'#ffb56f',12);worm.r=Math.min(20,9+Math.floor(score/5)*1.25);if(score%5===0){level++;notice('MUTATION '+String(level).padStart(2,'0')+' · '+upgrades[(level-1)%upgrades.length].name.toUpperCase());addSpark(worm.x,worm.y,'#d6f263',22)}updateHUD()}

