function eat(f){score+=f.value;addSpark(f.x,f.y,f.type==='root'?'#d6f263':'#ffb56f',12);worm.r=Math.min(20,9+Math.floor(score/5)*1.25);if(score%5===0){level++;notice('MUTATION '+String(level).padStart(2,'0')+' · '+upgrades[(level-1)%upgrades.length].name.toUpperCase());addSpark(worm.x,worm.y,'#d6f263',22)}updateHUD()}
function steerAngle(){let dx=0,dy=0;if(keys.ArrowLeft||keys.a||keys.A)dx--;if(keys.ArrowRight||keys.d||keys.D)dx++;if(keys.ArrowUp||keys.w||keys.W)dy--;if(keys.ArrowDown||keys.s||keys.S)dy++;if(dx||dy)return Math.atan2(dy,dx);if(pointer.active){let px=worm.x-camera.x,py=worm.y-camera.y;dx=pointer.x-px;dy=pointer.y-py;if(Math.hypot(dx,dy)>20)return Math.atan2(dy,dx)}return worm.angle}
function angleDiff(a,b){return Math.atan2(Math.sin(b-a),Math.cos(b-a))}
function update(dt){elapsed+=dt;let target=steerAngle(),turn=.075+level*.004;worm.angle+=clamp(angleDiff(worm.angle,target),-turn,turn);let speed=2.55+Math.min(score*.018,.85)+(level>=4?.25:0);let dx=Math.cos(worm.angle),dy=Math.sin(worm.angle);let wasUnder=worm.y>surface(worm.x)+worm.r*.35;
 if(worm.air>0){worm.air=Math.max(0,worm.air-dt);worm.vx+=(dx*speed-worm.vx)*Math.min(1,dt*2.7);worm.vy+=Math.sin(worm.angle)*speed*dt*1.7+460*dt;worm.vx*=Math.pow(.995,dt*60);worm.x+=worm.vx*dt*60;worm.y+=worm.vy*dt*60;if(worm.y>=surface(worm.x)-worm.r*.3){worm.y=surface(worm.x)+worm.r*.55;worm.air=0;worm.vy=Math.max(1,worm.vy*.35);addSpark(worm.x,worm.y,'#e5cc93',9)}}else{let actual=speed+(wasUnder?.55:0);worm.vx+=(dx*actual-worm.vx)*Math.min(1,dt*5);worm.vy+=(dy*actual-worm.vy)*Math.min(1,dt*5);worm.x+=worm.vx*dt*60;worm.y+=worm.vy*dt*60;
  if(wasUnder&&worm.y<=surface(worm.x)+worm.r*.4&&worm.vy<-.7&&Math.abs(worm.vx)+Math.abs(worm.vy)>3.4){let angleFactor=clamp(-worm.vy/(Math.hypot(worm.vx,worm.vy)||1),0,1);worm.air=clamp(.65+angleFactor*.9+(level>=1?.35:0),.55,1.8);worm.vy=-Math.max(4.5,Math.abs(worm.vy)*(.9+angleFactor*.8));worm.pop=1;addSpark(worm.x,surface(worm.x),'#d6f263',20);notice('BURST! · '+Math.round(worm.vy*-1)+' M/S')}
  if(worm.y<surface(worm.x)-worm.r*.35){worm.air=Math.max(worm.air,.38);worm.vy=Math.min(worm.vy,2)} }
 worm.invuln=Math.max(0,worm.invuln-dt);worm.pop=Math.max(0,worm.pop-dt*1.5);worm.hidden=worm.y>surface(worm.x)+worm.r;
 worm.trail.unshift({x:worm.x,y:worm.y});let trailLength=18+score*.45;while(worm.trail.length>trailLength)worm.trail.pop();camera.x+=(worm.x-w*.43-camera.x)*Math.min(1,dt*3);camera.y+=(worm.y-h*.55-camera.y)*Math.min(1,dt*3);
 for(let f of foods)f.phase+=dt*2;for(let i=foods.length-1;i>=0;i--){let f=foods[i];let pull=level>=3?clamp(1-dist(worm,f)/145,0,.8):0;if(pull){f.x+=(worm.x-f.x)*pull*dt;f.y+=(worm.y-f.y)*pull*dt}if(dist(worm,f)<worm.r+f.r+5){eat(f);foods.splice(i,1)}}
 while(foods.length<48){let x=worm.x+rand(500,1450);addFood(x)}
 for(let i=sparks.length-1;i>=0;i--){let p=sparks[i];p.x+=p.vx*dt*60;p.y+=p.vy*dt*60;p.vy+=120*dt;p.life-=dt;if(p.life<=0)sparks.splice(i,1)}
 if(threat>25){spawnTimer-=dt;if(spawnTimer<=0&&enemies.length<Math.floor(threat/26)){enemies.push({x:worm.x+rand(330,650),y:Math.min(surface(worm.x)-80,worm.y-rand(130,250)),cool:rand(.8,2),kind:threat>65&&Math.random()<.48?'tank':'heli',phase:rand(0,8),hp:1});spawnTimer=rand(5,9)-threat*.035}}
 for(let i=enemies.length-1;i>=0;i--){let e=enemies[i];e.phase+=dt;e.cool-=dt;let aim=worm.hidden&&level<5?surface(worm.x)-30:worm.y;if(e.kind==='heli'){e.x+=(worm.x+400-e.x)*dt*.12;e.y+=(surface(e.x)-105+Math.sin(e.phase*2)*16-e.y)*dt*.7}else{e.x+=(worm.x+180-e.x)*dt*.1;e.y=surface(e.x)-25}if(e.cool<0&&Math.abs(e.x-worm.x)<650){let a=Math.atan2(aim-e.y,worm.x-e.x),v=e.kind==='tank'?4.5:5.4;shots.push({x:e.x,y:e.y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,r:e.kind==='tank'?5:4,life:5});e.cool=e.kind==='tank'?2.4:1.55}if(e.x<worm.x-900)enemies.splice(i,1)}
 for(let i=shots.length-1;i>=0;i--){let b=shots[i];b.x+=b.vx*dt*60;b.y+=b.vy*dt*60;b.life-=dt;if(b.life<=0||b.y>surface(b.x)+20){shots.splice(i,1);continue}if(!worm.hidden&&worm.invuln<=0&&dist(worm,b)<worm.r+b.r+3){shots.splice(i,1);hit()}}
 if(worm.invuln<=0&&worm.air>0&&enemies.some(e=>dist(worm,e)<worm.r+22))hit();if(milestoneTimer>0){milestoneTimer-=dt;if(milestoneTimer<=0)$('#milestone').classList.remove('show')}
 if(score>3&&damage>=3)finish();updateHUD();
}
function hit(){damage++;worm.invuln=1.5;worm.vy=-5;worm.air=.45;addSpark(worm.x,worm.y,'#ff735d',16);notice(damage>=3?'WORM DOWN · ONE HIT LEFT':'DIRECT HIT · '+(3-damage)+' LEFT')}
function finish(){if(over)return;over=true;playing=false;$('#endSize').textContent=String(1+Math.floor(score/3));$('#endScore').textContent=score;$('#endLevel').textContent=level;$('#endCopy').textContent=score>24?'You got properly enormous. The countryside may never recover.':'A good first dig. The fields are still full of snacks.';$('#endOverlay').classList.remove('hidden')}

