function finish(){if(over)return;over=true;playing=false;$('#endSize').textContent=String(1+Math.floor(score/3));$('#endScore').textContent=score;$('#endLevel').textContent=level;$('#endCopy').textContent=score>24?'You got properly enormous. The countryside may never recover.':'A good first dig. The fields are still full of snacks.';$('#endOverlay').classList.remove('hidden')}
function drawBackground(){let sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#a6d9ce');sky.addColorStop(.58,'#e1e5c4');sky.addColorStop(1,'#e5c88f');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);let sx=(camera.x*.16)%w;ctx.fillStyle='#f8eab2';ctx.beginPath();ctx.arc(w*.78,Math.max(92,h*.23),35,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f8eab250';ctx.beginPath();ctx.arc(w*.78,Math.max(92,h*.23),51,0,Math.PI*2);ctx.fill();for(let i=0;i<5;i++){let x=((i*270-sx*1.1)%(w+300)+w+300)%(w+300)-80,y=80+(i%3)*53;ctx.fillStyle='#ffffff63';ctx.beginPath();ctx.ellipse(x,y,38,10,0,0,Math.PI*2);ctx.ellipse(x+25,y-5,24,12,0,0,Math.PI*2);ctx.ellipse(x+49,y,31,9,0,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#8cc6b3';ctx.beginPath();ctx.moveTo(0,h*.53);for(let x=0;x<=w+10;x+=12)ctx.lineTo(x,h*.5+Math.sin((x+camera.x*.18)*.003)*20);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill();ctx.fillStyle='#76b39f';ctx.beginPath();ctx.moveTo(0,h*.58);for(let x=0;x<=w+10;x+=10)ctx.lineTo(x,h*.56+Math.sin((x+camera.x*.32)*.004)*13);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill()}
